engine.fcFindings:
function fcFindings(read) {
  read = read || {};
  var style = read.style || {}, input = read.input || {}, paras = input.paragraphs || [], terms = input.terms || [];
  var CAP = 25, MOST = 0.6, CLIP = 70;
  function clean(s) { return String(s == null ? "" : s).replace(/[\s\u0000-\u001f]+/g, " ").trim(); }
  function clip(s) { s = clean(s); return s.length <= CLIP ? s : s.slice(0, CLIP - 1).replace(/\s+\S*$/, "") + "…"; }
  function around(t, at, len) {   // the words around a place in a paragraph
    var a = Math.max(0, at - 30), b = Math.min(t.length, at + len + 30);
    return (a > 0 ? "…" : "") + clean(t.slice(a, b)) + (b < t.length ? "…" : "");
  }
  var groups = [];
  // A group from items, each with a value: the usual value (most of them, at least MOST), the rest listed.
  function byMajority(key, title, rows, label, min) {
    rows = rows.filter(function (r) { return r.v != null; });
    if (rows.length < (min || 3)) return;
    var n = {}, order = [];
    rows.forEach(function (r) { var k = String(r.v); if (!n[k]) { n[k] = 0; order.push(k); } n[k]++; });
    if (order.length < 2) return;
    order.sort(function (a, b) { return n[b] - n[a]; });
    var top = order[0], share = n[top] / rows.length, name = function (k) { return label ? label(k) : k; };
    var odd = rows.filter(function (r) { return String(r.v) !== top; });
    // no one way holds most of them: the split, not every place (nothing to measure them against)
    if (share < MOST) {
      groups.push({ key: key, title: title, usual: null, share: Math.round(share * 100) / 100, count: 0, items: [],
        split: order.slice(0, 4).map(function (k) { return name(k) + " " + Math.round(n[k] / rows.length * 100) + "%"; }).join(" · ") });
      return;
    }
    groups.push({ key: key, title: title, usual: name(top), share: Math.round(share * 100) / 100, count: odd.length,
      items: odd.slice(0, CAP).map(function (r) { return { i: r.i, snippet: r.snippet, found: name(String(r.v)) }; }) });
  }
  // A group of places one rule finds (no majority needed: the document's own usual is given).
  function listed(key, title, usual, rows) {
    if (!rows.length) return;
    groups.push({ key: key, title: title, usual: usual, count: rows.length, items: rows.slice(0, CAP) });
  }
  var heads = {}, labelAt = {};
  (read.labelCandidates || []).forEach(function (c) { labelAt[c.i] = c; if (!c.runIn) heads[c.i] = c; });
  var toc = function (p) { return /^toc\s*\d$/i.test(String(p.styleBuiltIn || "")) || /^toc\s*\d$/i.test(clean(p.style)); };
  // The agreement itself: up to its signature block or its first exhibit — what follows (a project description, a
  // policy) is a document of its own, set its own way. Its look, headings, spacing and numbering are checked there only.
  var end = paras.length;
  for (var e = 10; e < paras.length; e++) {
    if (/^(IN WITNESS WHEREOF|EXHIBIT|APPENDIX|SCHEDULE|ANNEX|ATTACHMENT)\b/i.test(clean(paras[e] && paras[e].text))) { end = e; break; }
  }
  var main = function (i) { return i < end; };
  var body = [];
  paras.forEach(function (p, i) { var t = clean(p && p.text); if (main(i) && t.length >= 40 && !p.inTable && !toc(p) && !heads[i]) body.push({ p: p, i: i, t: t }); });

  // 1. Body text: its font, its size and its alignment, each against the document's usual.
  var size = function (s) { return s == null || s === "" ? null : Math.round(Number(s) * 2) / 2; };
  byMajority("body-font", "Body text in another font", body.map(function (b) { return { i: b.i, v: b.p.font || null, snippet: clip(b.t) }; }));
  byMajority("body-size", "Body text in another size", body.map(function (b) { return { i: b.i, v: size(b.p.sizePt), snippet: clip(b.t) }; }), function (v) { return v + " pt"; });
  byMajority("body-align", "Body text aligned differently", body.map(function (b) { return { i: b.i, v: b.p.align ? String(b.p.align).toLowerCase() : null, snippet: clip(b.t) }; }));

  // 2. Headings: each label's look (bold, italic, underlined, capitals) against the others of its level.
  var looks = {};
  (input.labels || []).forEach(function (x) { if (x && x.i != null) looks[x.i] = x; });
  var lookOf = function (f, label) {
    if (!f || f.bold == null || f.italic == null || f.underline == null) return null;
    var bits = [];
    if (f.bold) bits.push("bold");
    if (f.italic) bits.push("italic");
    if (f.underline && f.underline !== "None") bits.push("underlined");
    var letters = String(label).replace(/[^A-Za-z]/g, "");
    if (letters.length >= 2 && letters === letters.toUpperCase()) bits.push("capitals");
    return bits.length ? bits.join(" + ") : "plain";
  };
  var byGroup = {};
  (read.labelCandidates || []).forEach(function (c) {
    if (!main(c.i)) return;
    var k = String(c.group) + (c.runIn ? " run-in" : "");
    (byGroup[k] = byGroup[k] || []).push({ i: c.i, v: lookOf(looks[c.i], c.label), snippet: clip((c.number ? c.number + " " : "") + c.label) });
  });
  Object.keys(byGroup).forEach(function (k) {
    var lv = k.replace(/ run-in$/, ""), name = /^\d+$/.test(lv) ? "level " + lv : "“" + lv + "”";
    byMajority("heading-look-" + k.replace(/\W+/g, "_"), (/run-in$/.test(k) ? "Run-in headings" : "Headings") + " at " + name + " set differently", byGroup[k]);
  });

  // 3. Defined terms: their quotes, and their look, against the rest.
  byMajority("term-quotes", "Defined terms in other quotes", terms.map(function (t) { return { i: t.i, v: t.quote || null, snippet: clip(t.snippet || t.term) }; }),
    function (v) { return v === "curly" ? "curly quotes “ ”" : v === "straight" ? "straight quotes \" \"" : v; });
  byMajority("term-look", "Defined terms set differently", terms.map(function (t) {
    if (t.bold == null && t.italic == null && t.underline == null) return { v: null };
    var bits = [];
    if (t.bold) bits.push("bold");
    if (t.italic) bits.push("italic");
    if (t.underline) bits.push("underlined");
    return { i: t.i, v: bits.join(" + ") || "plain", snippet: clip(t.snippet || t.term) };
  }));

  // 4. Quotation marks and apostrophes in the text: curly or straight, the document's way.
  var qrows = [];
  paras.forEach(function (p, i) {
    var t = String((p && p.text) || "");
    var cur = (t.match(/[“”‘’]/g) || []).length, st = (t.match(/["']/g) || []).length;
    if (cur || st) qrows.push({ i: i, cur: cur, st: st, t: t });
  });
  var cTot = 0, sTot = 0;
  qrows.forEach(function (r) { cTot += r.cur; sTot += r.st; });
  if (cTot + sTot >= 10) {
    var curlyDoc = cTot >= sTot;
    var share = Math.max(cTot, sTot) / (cTot + sTot);
    if (share >= 0.8) listed("quotes", curlyDoc ? "Straight quotes or apostrophes where the document uses curly ones" : "Curly quotes or apostrophes where the document uses straight ones",
      curlyDoc ? "curly “ ” ’" : "straight \" '", qrows.filter(function (r) { return curlyDoc ? r.st : r.cur; }).map(function (r) {
        var at = r.t.search(curlyDoc ? /["']/ : /[“”‘’]/);
        return { i: r.i, snippet: around(r.t, at, 1), found: (curlyDoc ? r.st : r.cur) + " " + (curlyDoc ? "straight" : "curly") };
      }));
  }

  // 5. Dashes between words: a spaced hyphen ("fees - including") where the document uses a dash.
  var dash = 0, hy = [];
  paras.forEach(function (p, i) {
    var t = String((p && p.text) || "");
    dash += (t.match(/\s[–—]\s|\w—\w/g) || []).length;
    var m = /[\w"”’)\]] - [\w"“(]/.exec(t);
    if (m) hy.push({ i: i, snippet: around(t, m.index, 5), found: "a hyphen as a dash" });
  });
  if (dash >= 3 && dash >= hy.length * 2) listed("dashes", "A hyphen used as a dash", "a dash – between words", hy);

  // 6. Spaces: two after a full stop in some places, one in others; two between words.
  var two = [], one = [], gaps = [];
  paras.forEach(function (p, i) {
    if (!main(i)) return;
    var t = String((p && p.text) || "");
    var a = (t.match(/[a-z)\]”"][.!?]["”’)]? {2}[A-Z(“"]/g) || []).length, b = (t.match(/[a-z)\]”"][.!?]["”’)]? [A-Z(“"]/g) || []).length;
    if (a) two.push({ i: i, n: a, t: t });
    if (b) one.push({ i: i, n: b, t: t });
    var g = /[A-Za-z,;] {2,}[a-z]/.exec(t);
    if (g) gaps.push({ i: i, snippet: around(t, g.index, g[0].length), found: "two spaces between words" });
  });
  var twoN = two.reduce(function (s, r) { return s + r.n; }, 0), oneN = one.reduce(function (s, r) { return s + r.n; }, 0);
  if (twoN + oneN >= 10 && Math.max(twoN, oneN) / (twoN + oneN) >= 0.8 && Math.min(twoN, oneN) > 0) {
    var twoDoc = twoN > oneN, odd = twoDoc ? one : two, re = twoDoc ? /[.!?]["”’)]? [A-Z(“"]/ : /[.!?]["”’)]? {2}[A-Z(“"]/;
    listed("sentence-spaces", twoDoc ? "One space after a full stop where the document uses two" : "Two spaces after a full stop where the document uses one",
      twoDoc ? "two spaces" : "one space", odd.map(function (r) { var at = r.t.search(re); return { i: r.i, snippet: around(r.t, at, 3), found: twoDoc ? "one space" : "two spaces" }; }));
  }
  listed("word-spaces", "Two spaces between words", "one space", gaps);

  // 7. Cross-references: "Section 5.1" against "Clause 5.1" or "§ 5.1" (Article is its own level, never counted).
  var xr = [];
  paras.forEach(function (p, i) {
    var t = String((p && p.text) || ""), m, re = /\b(Section|section|Clause|clause)s?\s+\d{1,3}(?:\.\d{1,3})*|§§?\s?\d{1,3}(?:\.\d{1,3})*/g;
    if (toc(p || {})) return;
    while ((m = re.exec(t))) {
      if (m.index === 0 && labelAt[i]) continue;   // a heading's own number
      // a law's section, not the document's ("Virginia Code §2.2-1837", "15 U.S.C. § 78")
      if (/^§/.test(m[0]) && (/^§§?\s?\d[\d.]*-/.test(t.slice(m.index)) || /\b(Code|U\.\s?S\.\s?C\.?|C\.\s?F\.\s?R\.?|Act|Stat\.?)\s*$/i.test(t.slice(Math.max(0, m.index - 30), m.index)))) continue;
      var w = /^§/.test(m[0]) ? "§" : m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase() + (/^[a-z]/.test(m[1]) ? " (lower case)" : "");
      xr.push({ i: i, v: w, snippet: around(t, m.index, m[0].length) });
    }
  });
  byMajority("xrefs", "Cross-references written another way", xr, function (v) {
    return v === "§" ? "§ 5.1" : / \(lower case\)$/.test(v) ? v.replace(" (lower case)", "").toLowerCase() + " 5.1" : v + " 5.1";
  }, 5);

  // 8. Numbering: Word's own list numbers in most numbered paragraphs, typed numbers in a few (or the other way).
  var nrows = [];
  paras.forEach(function (p, i) {
    var t = clean(p && p.text);
    if (!t || !main(i) || (p && p.inTable) || toc(p || {})) return;
    if (p.listString != null) nrows.push({ i: i, v: "Word's numbering", snippet: clip(clean(p.listString) + " " + t) });
    else if (/^(\d{1,3}(?:\.\d{1,3})+\.?|\d{1,3}\.)\s+[A-Z]/.test(t)) nrows.push({ i: i, v: "typed numbers", snippet: clip(t) });
  });
  byMajority("numbering", "Numbers typed in, where Word numbers the rest (or the other way)", nrows, null, 5);

  groups.forEach(function (g) { g.items.forEach(function (x) { if (!x.snippet) x.snippet = clip((paras[x.i] || {}).text); }); });
  var odd = groups.reduce(function (s, g) { return s + g.count; }, 0);
  return {
    groups: groups,
    checked: { paragraphs: paras.length, body: body.length, headings: (read.labelCandidates || []).length, terms: terms.length },
    overview: groups.length ? odd + " place" + (odd === 1 ? "" : "s") + " set differently from the rest, in " + groups.length + " way" + (groups.length === 1 ? "" : "s") : "Set consistently throughout",
    provenance: { kernelVersion: String(input.kernelVersion || ""), toolVersion: String(input.toolVersion || ""), docHash: "", timestamp: input.now != null ? input.now : Date.now() },
  };
}

view.renderFormatCheck:
function renderFormatCheck(opts) {
  opts = opts || {};
  var r = opts.result || null, open = opts.open || {};
  function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
  function button(label, fn, cls) { var b = el("button", "_fc_btn btn-platinum" + (cls ? " " + cls : ""), label); b.type = "button"; b.onclick = function () { if (typeof fn === "function") fn(); }; return b; }
  var root = el("div", "_fc_root");
  var head = el("div", "_fc_head");
  head.appendChild(el("div", "_fc_title", "Format Check"));
  head.appendChild(el("div", "_fc_sub", "Where this document is set differently from the rest of it — read only, nothing is changed."));
  root.appendChild(head);
  if (opts.busy) { root.appendChild(el("div", "_fc_busy", "Reading the document's look…")); return root; }
  if (opts.error) {
    root.appendChild(el("div", "_fc_err", opts.error));
    var ea = el("div", "_fc_acts"); ea.appendChild(button("Try again", opts.onAgain)); root.appendChild(ea);
    return root;
  }
  if (!r) return root;
  var verdict = el("div", "_fc_verdict" + (r.groups.some(function (g) { return g.count; }) ? "" : " _fc_ok"), r.overview);
  root.appendChild(verdict);
  root.appendChild(el("div", "_fc_checked", r.checked.paragraphs + " paragraphs · " + r.checked.headings + " headings · " + r.checked.terms + " defined terms read"));
  r.groups.forEach(function (g) {
    var card = el("div", "_fc_card" + (g.count ? "" : " _fc_quiet"));
    var top = el("button", "_fc_card_top");
    top.type = "button";
    top.appendChild(el("span", "_fc_card_t", g.title));
    top.appendChild(el("span", "_fc_card_n", g.count ? String(g.count) : "—"));
    top.onclick = function () { if (typeof opts.onToggle === "function") opts.onToggle(g.key); };
    card.appendChild(top);
    card.appendChild(el("div", "_fc_usual", g.usual != null ? "Usually: " + g.usual + (g.share ? " (" + Math.round(g.share * 100) + "%)" : "") : "No one way holds most of them: " + (g.split || "")));
    if (g.count && open[g.key]) {
      var list = el("div", "_fc_list");
      g.items.forEach(function (x) {
        var row = el("button", "_fc_item");
        row.type = "button";
        row.appendChild(el("span", "_fc_found", x.found));
        row.appendChild(el("span", "_fc_snip", x.snippet || ""));
        row.title = "Go to it in Word";
        row.onclick = function () { if (typeof opts.onGo === "function") opts.onGo(x.i); };
        list.appendChild(row);
      });
      if (g.count > g.items.length) list.appendChild(el("div", "_fc_more", "… and " + (g.count - g.items.length) + " more"));
      card.appendChild(list);
    }
    root.appendChild(card);
  });
  var acts = el("div", "_fc_acts");
  acts.appendChild(button("Check again", opts.onAgain));
  acts.appendChild(button("Back", opts.onBack));
  root.appendChild(acts);
  return root;
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["format_check"];
  var find = bundle && bundle._eliEngineFns && bundle._eliEngineFns.fcFindings;
  var render = bundle && bundle._eliViewFns && bundle._eliViewFns.renderFormatCheck;
  if (!find || !render) { eli.log.event("tool", "format_check_init_missing_fns", { find: !!find, render: !!render }); return; }
  var state = { result: null, busy: false, error: "", open: {} };

  function paint() {
    var node = render({ result: state.result, busy: state.busy, error: state.error, open: state.open,
      onGo: go, onToggle: function (k) { state.open[k] = !state.open[k]; paint(); }, onAgain: run,
      onBack: function () { if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome(); } });
    var prev = document.querySelector("._fc_root");
    if (prev && prev.parentNode) { prev.parentNode.replaceChild(node, prev); return; }
    var out = eli.ui.claimOutput();
    if (!out) { if (typeof showToast === "function") showToast("Format Check couldn't find the panel.", "err"); return; }
    out.appendChild(node);
  }
  // doc_style's reading with its input (the paragraphs, terms and label looks it measured), then the findings.
  function run() {
    state.busy = true; state.error = ""; paint();
    var t0 = Date.now();
    return Promise.resolve(eli.tools.ensureLoaded("doc_style")).then(function () {
      var read = eli.get && eli.get("doc_style", "read");
      if (typeof read !== "function") throw new Error("ELI's document-style reader isn't installed.");
      return read({ withInput: true });
    }).then(function (a) {
      if (!a || !a.input) throw new Error("This version of ELI's document-style reader can't share what it read — update ELI's tools, then check again.");
      var r = find(a);
      state.result = r;
      eli.log.event("tool", "format_check_run", { groups: r.groups.length, places: r.groups.reduce(function (s, g) { return s + g.count; }, 0), paragraphs: r.checked.paragraphs, ms: Date.now() - t0 });
    }).catch(function (e) {
      state.error = "Format Check couldn't read the document: " + String((e && e.message) || e);
    }).then(function () { state.busy = false; paint(); });
  }
  // A place: its paragraph selected in Word (the structural map's bookmark for it).
  function go(i) {
    if (!eli.host || typeof eli.host.readStructuralMap !== "function") return;
    return eli.host.readStructuralMap({ prefix: "ELI_IDX_" }).then(function (map) {
      var row = map && map.byParagraphIdx && map.byParagraphIdx[i];
      if (!row || !row.anchor) return;
      return eli.host.runRaw("format_check:go", function (ctx) {
        var r = ctx.document.getBookmarkRangeOrNullObject(row.anchor);
        r.load("isNullObject");
        return ctx.sync().then(function () { if (!r.isNullObject) { r.select(); return ctx.sync(); } });
      });
    }).catch(function () {});
  }
  eli.register({ tile: { app_format_check: function () { state.open = {}; run(); } } });
}

jsonTools.css:
/* tools/format_check/style.css — Format Check's panel ([FMT-CHECK]): light in both themes, one gold accent. */
._fc_root { background: #f8fafc; color: #0f1f3d; padding: 14px 14px 18px; font: 14px/1.45 "Segoe UI", system-ui, sans-serif; min-height: 100%; box-sizing: border-box; }
._fc_head { border-bottom: 2px solid #c9a227; padding-bottom: 10px; margin-bottom: 12px; }
._fc_title { font: 600 19px/1.2 Georgia, serif; color: #0f1f3d; }
._fc_sub { margin-top: 4px; color: #475569; font-size: 12.5px; }
._fc_busy, ._fc_err { padding: 14px 12px; border: 1px solid #e2e8f0; background: #fff; color: #334155; }
._fc_err { border-color: #f1c4c0; color: #9b2c22; }
._fc_verdict { font: 600 15px/1.35 Georgia, serif; color: #0f1f3d; margin: 2px 0 2px; }
._fc_verdict._fc_ok { color: #166534; }
._fc_checked { color: #64748b; font-size: 12px; margin-bottom: 12px; }
._fc_card { background: #fff; border: 1px solid #e2e8f0; border-left: 3px solid #c9a227; margin-bottom: 9px; }
._fc_card._fc_quiet { border-left-color: #cbd5e1; }
._fc_card_top { display: flex; width: 100%; align-items: baseline; gap: 10px; padding: 10px 12px 2px; background: none; border: 0; text-align: left; cursor: pointer; color: inherit; font: inherit; }
._fc_card_t { flex: 1; font-weight: 600; color: #0f1f3d; }
._fc_card_n { flex: none; min-width: 22px; text-align: center; padding: 1px 6px; border: 1px solid #c9a227; color: #7a5d0b; font: 700 11px/1.5 "Segoe UI", system-ui, sans-serif; }
._fc_quiet ._fc_card_n { border-color: #cbd5e1; color: #64748b; }
._fc_usual { padding: 0 12px 10px; color: #475569; font-size: 12.5px; }
._fc_list { border-top: 1px solid #eef2f7; padding: 4px 0; }
._fc_item { display: block; width: 100%; text-align: left; padding: 6px 12px; background: none; border: 0; cursor: pointer; color: inherit; font: inherit; }
._fc_item:hover { background: #f8f5e8; }
._fc_found { display: inline-block; margin-right: 8px; padding: 0 6px; background: #fdf6e3; color: #7a5d0b; font-size: 11.5px; font-weight: 600; }
._fc_snip { color: #334155; font: 13px/1.4 Georgia, serif; }
._fc_more { padding: 4px 12px 8px; color: #64748b; font-size: 12px; }
._fc_acts { display: flex; gap: 8px; margin-top: 14px; }
._fc_btn { padding: 7px 14px; font: 600 12.5px/1 "Segoe UI", system-ui, sans-serif; cursor: pointer; }
